#[cfg(test)]
mod tests {
    use chrono::Utc;
    use rigorix_engine::capacity_ledger::domain::IdempotencyKey;
    use rigorix_engine::effect_commitment::domain::{
        CommitmentError, EffectIntent, EffectQuery, EffectRecord, EffectRecordId, EffectState,
        ObservedOutcome, ResolverIdentity, ResolverKind,
    };
    use uuid::Uuid;

    fn intent() -> EffectIntent {
        EffectIntent::new(
            Uuid::from_u128(1),
            Uuid::from_u128(2),
            1,
            IdempotencyKey::new("intent-key"),
            "payments.charge",
            "args-digest",
            "precondition-digest",
            "authority-digest",
        )
    }

    fn evidence() -> ObservedOutcome {
        ObservedOutcome::committed("receipt-1", "readback-1", Utc::now(), "stripe")
    }

    fn resolver() -> ResolverIdentity {
        ResolverIdentity::new("stripe-readback", ResolverKind::Provider, "readback-1")
    }

    #[test]
    fn test_effectrecord_is_defined() {
        let record = EffectRecord::begin(intent());
        assert_eq!(record.state(), EffectState::Dispatched);
        assert!(!record.is_terminal());
        assert!(!record.blocks_dependents());
        assert!(!record.blocks_retry());
        assert!(!record.has_evidence());
        assert!(record.outcome().is_none());
        assert_eq!(record.intent().tool, "payments.charge");
    }

    #[test]
    fn test_effectrecord_interacts_with_effectintent() {
        // A definite observation settles a dispatched record, and a terminal
        // record always carries its evidence.
        let record = EffectRecord::begin(intent())
            .settle_definite(evidence(), Utc::now())
            .expect("settle a dispatched record");
        assert_eq!(record.state(), EffectState::Committed);
        assert!(record.is_terminal());
        assert!(record.has_evidence());
        assert!(record.outcome().is_some());

        // A terminal record cannot be settled twice.
        let replay = record.clone().settle_definite(evidence(), Utc::now());
        assert!(matches!(
            replay,
            Err(CommitmentError::AlreadySettled { .. })
        ));
    }

    #[test]
    fn test_effectrecord_interacts_with_effectstate() {
        // Lost response / crash: the record becomes Ambiguous, which fences
        // both dependents and retry.
        let ambiguous = EffectRecord::begin(intent())
            .mark_ambiguous("response lost in flight", Utc::now())
            .expect("mark dispatched ambiguous");
        assert_eq!(ambiguous.state(), EffectState::Ambiguous);
        assert!(!ambiguous.is_terminal());
        assert!(ambiguous.blocks_dependents());
        assert!(ambiguous.blocks_retry());
        assert_eq!(
            ambiguous.ambiguous_reason(),
            Some("response lost in flight")
        );

        // An ambiguous record cannot be settled without a resolver — that path
        // is `resolve`, not `settle_definite`.
        assert!(matches!(
            ambiguous.clone().settle_definite(evidence(), Utc::now()),
            Err(CommitmentError::NotAmbiguous { .. })
        ));

        // A dispatched record cannot skip straight to resolve.
        assert!(matches!(
            EffectRecord::begin(intent()).resolve(evidence(), resolver(), Utc::now()),
            Err(CommitmentError::NotAmbiguous { .. })
        ));

        let resolved = ambiguous
            .resolve(evidence(), resolver(), Utc::now())
            .expect("resolve with provider evidence");
        assert_eq!(resolved.state(), EffectState::Committed);
        assert_eq!(
            resolved.resolver().map(|r| r.kind),
            Some(ResolverKind::Provider)
        );
        assert!(resolved.has_evidence());
    }

    #[test]
    fn test_effectrecord_hydrate_rejects_terminal_without_evidence() {
        let result = EffectRecord::hydrate(
            EffectRecordId::new(),
            intent(),
            EffectState::Committed,
            None,
            None,
            None,
            Utc::now(),
        );
        assert!(matches!(
            result,
            Err(CommitmentError::EvidenceMissing { .. })
        ));

        // A well-formed persisted record hydrates.
        let hydrated = EffectRecord::hydrate(
            EffectRecordId::new(),
            intent(),
            EffectState::Ambiguous,
            None,
            None,
            Some("lost".to_string()),
            Utc::now(),
        )
        .expect("ambiguous without evidence is representable");
        assert!(hydrated.blocks_retry());
    }

    #[test]
    fn test_effectrecord_matches_ledger_queries() {
        let record = EffectRecord::begin(intent());

        assert!(record.matches_query(&EffectQuery::by_id(record.id())));
        assert!(!record.matches_query(&EffectQuery::by_id(EffectRecordId::new())));
        assert!(record.matches_query(&EffectQuery::by_dag(Uuid::from_u128(1))));
        assert!(!record.matches_query(&EffectQuery::by_dag(Uuid::from_u128(999))));

        // The ambiguous query lists only unsettled records, optionally by DAG.
        assert!(!record.matches_query(&EffectQuery::ambiguous(None)));
        let ambiguous = record.clone().mark_ambiguous("lost", Utc::now()).unwrap();
        assert!(ambiguous.is_ambiguous());
        assert!(ambiguous.matches_query(&EffectQuery::ambiguous(None)));
        assert!(ambiguous.matches_query(&EffectQuery::ambiguous(Some(Uuid::from_u128(1)))));
        assert!(!ambiguous.matches_query(&EffectQuery::ambiguous(Some(Uuid::from_u128(999)))));
    }
}
